T=True
def N(sh, text, say=None): return [sh, None, text, None, None, None, say]
def C(sh, who, text, bubble=None, emo=None, think=False, say=None): return [sh, who, text, bubble, think, emo, say]
TAGS = lambda *x: list(x)[:5]
def R(id, title, caption, tags, comment, voices, lines, spec, assets=None, fx=None):
    d = dict(id=id, title=title, caption=caption, tags=tags, comment=comment, voices=voices, lines=lines, spec=spec)
    if assets: d['assets'] = assets
    if fx: d['fx'] = fx
    return d
